#include <stdio.h>

int main(void) {
    int a[] = {5, 13, 19, 21, 37, 56, 64, 75, 80, 88};
    int n = (int)(sizeof(a) / sizeof(a[0]));
    int key = 21;
    int lo = 0, hi = n - 1, mid = 0, cnt = 0, pos = -1;
    int found;
    const char *res;
    int h = 0, t = n + 1;
    while (lo <= hi) {
        mid = lo + (hi - lo) / 2;
        cnt++;
        if (a[mid] == key) { pos = mid; break; }
        else if (a[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    found = (pos >= 0) ? 1 : 0;
    res = found ? "是" : "否";
    while (t > 1) { t = (t + 1) / 2; h++; }
    printf("折半查找  n=%d  key=%d\n", n, key);
    printf("比较次数=%d  位置下标=%d  找到=%s\n", cnt, pos, res);
    printf("判定树高度 h=ceil(log2(n+1))=%d\n", h);
    printf("最坏比较次数 = 判定树高度 = %d\n", h);
    return 0;
}
